@Transactional
public Map createClosure(String regionId, ClosureRequest req) {
    ensureRegion, lock
    replay: findClosureByRequestId(req.requestId()) — if present: if region matches and reason matches → return existing; else 409.
    if status == CLOSED → 409 REGION_ALREADY_CLOSED
    insert closure MANUAL, update status CLOSED
}
