@Transactional
public Map createReview(String regionId, ReviewCreateRequest req) {
    now; ensureRegion; lock status
    replay: findByRequestId(req.requestId()) → if present and region matches → return existing review view; else 409
    if status != CLOSED → 409 REGION_NOT_CLOSED
    Instant end = now truncated to hour minus 1 hour? Window = last 3 full hours: H = now.truncatedTo(HOURS); hours H-3, H-2, H-1.
    List<ReadingRec> readings = for each hour findByHour → missing → 422 MISSING_HOURLY_READING
    if any newSnowCm > 5 → 422 OVER_LIMIT_IN_WINDOW
    insert review with readingIds snapshot
    return view
}

@Transactional
public Map confirm(long reviewId, ConfirmationRequest req) {
    review = reviewDao.findById(reviewId) or 404
    ensureRegion + lock region
    replay: findConfirmationByRequestId → if present: if reviewId & reviewer match → return current review view; else 409
    if review.status != PENDING → 409 REVIEW_NOT_PENDING (INVALIDATED → include reason; COMPLETED → 409)
    if region status != CLOSED → 409 REGION_NOT_CLOSED (can't unseal a region that got reopened/re-closed... actually if region is OPEN something's off)
    // consistent snapshot re-check
    re-read the 3 readings by ids; verify each newSnowCm <= 5 else 422 (shouldn't happen since immutable, but consistency guard)
    if review.firstReviewer == null:
        setFirstReviewer, insertConfirmation(seq=1)
