                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"" + reqId() + "\",\"reviewer\":\"alice\"}"))
                .andExpect(status().isOk());
        mvc.perform(post("/api/unseal-reviews/{id}/confirmations", reviewId)
